from pathlib import Path
import json,gzip,re,datetime,hashlib
out=Path('00_nucleo/diagnosticos/tekt-v16-introspect-walk-2026-10-16');scope=json.load(open(out/'scope.json'));tests=json.load(gzip.open(out/'tests-and-l0.json.gz'));record={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'changes':[]}
for source in scope['sources']:assert Path(source).read_text()==tests[source]
p=Path(scope['sources'][0]);s=p.read_text();matches=list(re.finditer(r'^(\s*)_ => (\{\}|false|None)(,?)$',s,re.M));assert len(matches)==6,len(matches)
for m,item in reversed(list(zip(matches,scope['targets']))):
 indent=m.group(1);assert '\n' not in indent
 patterns=[v for n,v in scope['variants'].items() if n not in item['excluded']];assert len(patterns)==item['group_size']
 replacement=indent+('\n'+indent+'| ').join(patterns)+' => '+m.group(2)+m.group(3);s=s[:m.start()]+replacement+s[m.end():];record['changes'].append({**item,'patterns':patterns,'old':m.group(0),'new':replacement})
s=s.replace('assert!(intr.kind_index.get(&ElementKind::Heading).is_none());','assert!(!intr.kind_index.contains_key(&ElementKind::Heading));');p.write_text(s)
p=Path('01_core/src/compiler/introspect/extract_payload.rs');s=p.read_text();needle='        Content::Heading(h) => h.to_payload(),';assert s.count(needle)==1;s=s.replace(needle,needle+'\n        Content::OutlineEntry(e) => e.to_payload(),',1);needle='        | Content::OutlineEntry(_)\n';assert s.count(needle)==1;s=s.replace(needle,'',1);s=s.replace('Delegações e exceções são prescritas no L0; OutlineEntry mantém caminho sintetizado.','OutlineEntry delega ao elemento; a síntese pós-walk mantém sua responsabilidade.').replace('OutlineEntry conserva seu caminho sintetizado; Source já foi normalizado.','Source já foi normalizado e não possui payload próprio.');p.write_text(s)
p=Path('01_core/src/entities/elements/outline_entry.rs');s=p.read_text();needle='        match &self.element {';assert s.count(needle)==1;p.write_text(s.replace(needle,'        match self.element.source_body() {',1))
p=Path('01_core/src/compiler/layout/realized.rs');s=p.read_text();head,rest=s.split('fn prepared_locations',1);needle='        Content::Outline(_)\n';assert head.count(needle)==1;head=head.replace(needle,needle+'        | Content::OutlineEntry(_)\n',1);needle='        | Content::OutlineEntry(_)\n';assert head.count(needle)==2;first=head.index(needle);second=head.index(needle,first+len(needle));head=head[:second]+head[second+len(needle):];p.write_text(head+'fn prepared_locations'+rest)
p=Path('01_core/src/compiler/introspect/locatable.rs');s=p.read_text();s=s.replace('//! `is_locatable(c) == extract_payload(c).is_some()`. OutlineEntry mantém\n//! alinhamento pendente com o caminho sintetizado; Dynamic delega ao elemento.','//! `is_locatable(c) == extract_payload(c).is_some()`, incluindo OutlineEntry.\n//! A síntese pós-walk permanece separada; Dynamic delega ao elemento.').replace('/// construir payload ou calcular hash. OutlineEntry usa caminho sintetizado;\n/// Dynamic depende do contrato de kind/payload do elemento.','/// construir payload ou calcular hash. OutlineEntry tem delegação nativa;\n/// Dynamic depende do contrato de kind/payload do elemento.');p.write_text(s)
for source in scope['sources']:
 p=Path(source);s=p.read_text();s=re.sub(r'^//! @updated .*$', '//! @updated 2026-10-16',s,count=1,flags=re.M);p.write_text(s)
record['expected_before_fmt']={p:Path(p).read_text() for p in scope['sources']};(out/'materialization.json').write_text(json.dumps(record,indent=2)+'\n');print('Prescribed implementation applied',flush=True)
